	Sas = 2,
	/** Toggle RCS. */
	Rcs = 3,
	/** Toggle the lights. */
	Lights = 4,
	/** Toggle the landing gear. */
	Gear = 5,
	/** Toggle the brakes. */
	Brakes = 6,
	/** Toggle the abort action group. */
	Abort = 7
